package org.sleepwell.app;
import android.app.*;import android.os.*;import android.widget.*;

/** Explicit template save. Merely opening, rotating or leaving this screen never changes an alarm. */
public final class AlarmDefaultsActivity extends Activity implements AlarmDefaultsSave.Observer {
    private AlarmDefaults selected;private AlarmDefaultsSave job;private String readError="";
    @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);try{selected=AlarmDefaultsJson.decode(saved==null?getIntent().getStringExtra("template"):saved.getString("template"));}catch(IllegalArgumentException invalid){finish();return;}Object retained=getLastNonConfigurationInstance();job=retained instanceof AlarmDefaultsSave?(AlarmDefaultsSave)retained:new AlarmDefaultsSave(AlarmDefaultsSettings.factory.open(getApplicationContext()));try{readError=job.port.read().error;}catch(RuntimeException unavailable){readError="Saved defaults could not be read.";}job.observe(this);}
    @Override public Object onRetainNonConfigurationInstance(){return job;}
    @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("template",AlarmDefaultsJson.encode(selected));}
    @Override public void changed(){if(isDestroyed())return;LinearLayout body=Design.page(this,false,null,null);Design.header(body,"New alarm defaults",this::finish);Design.space(body,16);Design.text(body,"Use this draft’s behavior for future alarms.",15,400,Design.MUTED);Design.space(body,20);Alarm value=selected.create(1);PlanActivity.detail(body,"tasks","Challenges",value.challenges().summary(),null,null);PlanActivity.detail(body,"sound","Sound",AlarmEditorActivity.toneName(value.tone),value.volume+"%",null);PlanActivity.detail(body,"sun","Gentle increase",value.rampSeconds==0?"Off":value.rampSeconds+" sec",null,null);PlanActivity.detail(body,"alarm","Snooze",value.snoozeMinutes+" min",value.snoozeLimit+" maximum",null);Design.space(body,16);Design.text(body,"Includes wake-up, sound, challenge and snooze settings. Each new alarm starts off at 7:00 with no repeat days. Existing alarms stay as saved.",13,400,Design.MUTED);Design.space(body,16);android.view.View reset=Design.button(body,"Restore factory defaults",false,()->job.start(null));RecordUi.enabled(reset,!job.busy);LinearLayout footer=RecordUi.footer(body);String message=!job.error.isEmpty()?job.error:job.saved?(job.reset?"Factory defaults restored.":"Saved for new alarms."):readError;TextView status=Design.text(footer,message,13,500,!job.error.isEmpty()||!readError.isEmpty()?0xffa93919:Design.BROWN);status.setContentDescription("Alarm defaults status");status.setVisibility(message.isEmpty()?android.view.View.GONE:android.view.View.VISIBLE);status.setAccessibilityLiveRegion(android.view.View.ACCESSIBILITY_LIVE_REGION_POLITE);android.view.View save=Design.button(footer,job.busy?"Saving…":"Save new alarm defaults",true,()->job.start(selected));RecordUi.enabled(save,!job.busy);}
    boolean awaitWorkers(long millis)throws InterruptedException{return job.awaitClosed(millis);}
    @Override protected void onDestroy(){if(job!=null){job.detach();if(!isChangingConfigurations())job.close();}super.onDestroy();}
    @Override protected void onPostResume(){super.onPostResume();RecordUi.lightBars(this);}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
